    # ---------- 71. 溪亭二首 ----------
    {
        "id": "xu-hun-71",
        "title": "溪亭二首",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷73》",
        "verse": [
            "溪亭四面山，横柳半溪湾。蝉响螳螂急，鱼深翡翠闲。",
            "水寒留客醉，月上与僧还。犹恋萧萧竹，西斋未掩关。",
            "暖枕眠溪柳，僧斋昨夜期。茶香秋梦后，松韵晚吟时。",
            "共戏鱼翻藻，争栖鸟坠枝。重阳应一醉，栽菊助东篱。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
