    # ---------- 366. 寄当涂李远 ----------
    {
        "id": "xu-hun-366",
        "title": "寄当涂李远",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷37》",
        "verse": [
            "赋拟相如诗似陶，云阳烟月又同袍。车前骥病驽骀逸，",
            "架上鹰闲鸟雀高。旧日乐贫能饮水，他时随俗愿餔糟。",
            "不须倚向青山住，咏雪题诗用意劳。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 367. 和崔大夫新广北楼登眺 ----------
    {
        "id": "xu-hun-367",
        "title": "和崔大夫新广北楼登眺",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷38》",
        "verse": [
            "北望高楼夏亦寒，山重水阔接长安。修梁暗换丹楹小，",
            "疏牖全开彩槛宽。风卷浮云披睥睨，露凉明月坠阑干。",
            "庾公恋阙怀乡处，目送归帆下远滩。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 368. 送客自两河归江南（一作西河送客归江南） ----------
    {
        "id": "xu-hun-368",
        "title": "送客自两河归江南（一作西河送客归江南）",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷39》",
        "verse": [
            "两河庶事已堪伤，南客秋归路更长。台畔古松悲魏帝，",
            "苑边修竹吊梁王。山行露变茱萸色，水宿风披菡萏香。",
            "遥羡落帆逢旧友，绿蛾青鬓醉横塘。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 369. 题陆侍御林亭 ----------
    {
        "id": "xu-hun-369",
        "title": "题陆侍御林亭",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷40》",
        "verse": [
            "野水通池石叠台，五营无事隐雄才。松斋下马书千卷，",
            "兰舫逢人酒一杯。寒树雪晴红艳吐，远山云晓翠光来。",
            "定知别后无多日，海柳江花次第开。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 370. 泊蒜山津闻东林寺光仪上人物故 ----------
    {
        "id": "xu-hun-370",
        "title": "泊蒜山津闻东林寺光仪上人物故",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷41》",
        "verse": [
            "云斋曾宿借方袍，因说浮生大梦劳。言下是非齐虎尾，",
            "宿来荣辱比鸿毛。孤舟千棹水犹阔，寒殿一灯夜更高。",
            "明日东林有谁在，不堪秋磬拂烟涛。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 371. 春日思旧游寄南徐从事刘三复 ----------
    {
        "id": "xu-hun-371",
        "title": "春日思旧游寄南徐从事刘三复",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷42》",
        "verse": [
            "风暖曲江花半开，忽思京口共衔杯。湘潭云尽暮山出，",
            "巴蜀雪消春水来。怀玉尚悲迷楚塞，捧金犹羡乐燕台。",
            "蓟门高处极归思，陇雁北飞双燕回。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 372. 郊园秋日寄洛中友人 ----------
    {
        "id": "xu-hun-372",
        "title": "郊园秋日寄洛中友人",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷43》",
        "verse": [
            "楚水西来天际流，感时伤别思悠悠。一尊酒尽青山暮，",
            "万里书回碧树秋。日落远波惊宿雁，风吹轻浪起眠鸥。",
            "嵩阳亲友如相问，潘岳闲居欲白头。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 373. 送杜秀才归桂林 ----------
    {
        "id": "xu-hun-373",
        "title": "送杜秀才归桂林",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷44》",
        "verse": [
            "桂州南去与谁同，处处山连水自通。两岸晓霞千里草，",
            "半帆斜日一江风。瘴雨欲来枫树黑，火云初起荔枝红。",
            "愁君路远销年月，莫滞三湘五岭中。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 374. 春雨舟中次和横江裴使君见迎李赵二秀才同来…寄江南 ----------
    {
        "id": "xu-hun-374",
        "title": "春雨舟中次和横江裴使君见迎李赵二秀才同来…寄江南",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷45》",
        "verse": [
            "芳草渡头微雨时，万株杨柳拂波垂。蒲根水暖雁初落，",
            "梅径香寒蜂未知。词客倚风吹暗淡，使君回马湿旌旗。",
            "江南仲蔚多情调，怅望青云几首诗。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 375. 东陵赴京道病东归寓居开元寺寄卢员外宋魏二先辈 ----------
    {
        "id": "xu-hun-375",
        "title": "东陵赴京道病东归寓居开元寺寄卢员外宋魏二先辈",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷46》",
        "verse": [
            "西风吹雨雁初时，病寄僧斋罢献书。万里咸秦劳我马，",
            "四邻松桂忆吾庐。沧洲有约心还静，青汉无媒迹自疏。",
            "不是醉眠愁不散，莫言琴酒学相如。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 376. 闻开江宋相公申锡下世二首 ----------
    {
        "id": "xu-hun-376",
        "title": "闻开江宋相公申锡下世二首",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷47》",
        "verse": [
            "权门阴奏夺移才，馹骑如星堕峡来。晁氏有恩忠作祸，",
            "贾生无罪直为灾。贞魂误向崇山殁，冤气疑从汨水回。",
            "毕竟功成何处是，五湖云月一帆开。",
            "月落湘潭棹不喧，玉杯瑶瑟奠蘋蘩。谁能力制乘时鹤，",
            "自取机沉在槛猿。位极乾坤三事贵，谤兴华夏一夫冤。",
            "宵衣旰食明天子，日伏青蒲不敢言。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 377. 赠所知 ----------
    {
        "id": "xu-hun-377",
        "title": "赠所知",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷48》",
        "verse": [
            "因钓鲈鱼住浙河，挂帆千里亦相过。茅檐夜醉平阶月，",
            "兰棹春归拍岸波。湖日似阴鼍鼓响，海云才起蜃楼多。",
            "明时又作闲居赋，谁荐东门策四科。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 378. 谢人赠鞭 ----------
    {
        "id": "xu-hun-378",
        "title": "谢人赠鞭",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷49》",
        "verse": [
            "蜀国名鞭见惠稀，驽骀从此长光辉。独根拥肿来云岫，",
            "紫陌提携在绣衣。几度拂花香里过，也曾敲镫月中归。",
            "莫言三尺长无用，百万军中要指挥。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 379. 早秋寄刘尚书 ----------
    {
        "id": "xu-hun-379",
        "title": "早秋寄刘尚书",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷50》",
        "verse": [
            "天生心识富人侯，将相门中第一流。旗纛早开擒虎帐，",
            "戈鋋初发斩鲸舟。柳营书号海山暝，菌阁赋诗江树秋。",
            "昨夜雨凉今夜月，笙歌应醉最高楼。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 380. 及第后春情 ----------
    {
        "id": "xu-hun-380",
        "title": "及第后春情",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷51》",
        "verse": [
            "世间得意是春风，散诞经过触处通。细摇柳脸牵长带，",
            "慢撼桃株舞碎红。也从吹幌惊残梦，何处飘香别故丛。",
            "犹以西都名下客，今年一月始相逢。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 381. 归长安 ----------
    {
        "id": "xu-hun-381",
        "title": "归长安",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷52》",
        "verse": [
            "三年何处泪汍澜，白帝城边晓角残。非是无心恋巫峡，",
            "自缘□臂到长安。黔江水暖还曾饮，楚岫云深不识寒。",
            "大抵莫教闻雨后，此时肠断不应难。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 382. 经古行宫 ----------
    {
        "id": "xu-hun-382",
        "title": "经古行宫",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷53》",
        "verse": [
            "台阁参差倚太阳，年年花发满山香。重门勘锁青春晚，",
            "深院垂帘白昼长。草色芊绵侵御路，泉声呜咽绕宫墙。",
            "先皇一去无回驾，红粉云鬟空断肠。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 383. 秋晚怀茅山石涵村舍 ----------
    {
        "id": "xu-hun-383",
        "title": "秋晚怀茅山石涵村舍",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷54》",
        "verse": [
            "十亩山田近石涵，村居风俗旧曾谙。帘前白艾惊春燕，",
            "篱上青桑待晚蚕。云暖采茶来岭北，月明沽酒过溪南。",
            "陵阳秋尽多归思，红树萧萧覆碧潭。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 384. 贵游 ----------
    {
        "id": "xu-hun-384",
        "title": "贵游",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷55》",
        "verse": [
            "朝回佩马早凄凄，年少恩深卫霍齐。斧钺旧威龙塞北，",
            "池台新赐凤城西。门通碧树开金锁，楼对青山倚玉梯。",
            "南陌行人尽回首，笙歌一曲暮云低。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 385. 赠别 ----------
    {
        "id": "xu-hun-385",
        "title": "赠别",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷56》",
        "verse": [
            "眼前迎送不曾休，相续轮蹄似水流。门外若无南北路，",
            "人间应免别离愁。苏秦六印归何日，潘岳双毛去值秋。",
            "莫怪分襟衔泪语，十年耕钓忆沧洲。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 386. 秋夜与友人宿 ----------
    {
        "id": "xu-hun-386",
        "title": "秋夜与友人宿",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷57》",
        "verse": [
            "楚国同游过十霜，万重心事几堪伤。蒹葭露白莲塘浅，",
            "砧杵夜清河汉凉。云外山川归梦远，天涯岐路客愁长。",
            "寒城欲晓闻吹笛，犹卧东轩月满床。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 387. 将赴京留赠僧院 ----------
    {
        "id": "xu-hun-387",
        "title": "将赴京留赠僧院",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷58》",
        "verse": [
            "九衢尘土递追攀，马迹轩车日暮间。玄发尽惊为客换，",
            "白头曾见几人闲。空悲浮世云无定，多感流年水不还。",
            "谢却从前受恩地，归来依止叩禅关。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 388. 寄湘中友人 ----------
    {
        "id": "xu-hun-388",
        "title": "寄湘中友人",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷59》",
        "verse": [
            "莫恋醉乡迷酒杯，流年长怕老年催。西陵水阔鱼难到，",
            "南国路遥书未回。匹马计程愁日尽，一蝉何事引秋来。",
            "相如已定题桥志，江上无由梦钓台。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 389. 江上逢友人 ----------
    {
        "id": "xu-hun-389",
        "title": "江上逢友人",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷60》",
        "verse": [
            "故国归人酒一杯，暂停兰棹共徘徊。村连三峡暮云起，",
            "潮送九江寒雨来。已作相如投赋计，还凭殷浩寄书回。",
            "到时若见东篱菊，为问经霜几度开。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 390. 金谷怀古 ----------
    {
        "id": "xu-hun-390",
        "title": "金谷怀古",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷61》",
        "verse": [
            "凄凉遗迹洛川东，浮世荣枯万古同。桃李香销金谷在，",
            "绮罗魂断玉楼空。往年人事伤心外，今日风光属梦中。",
            "□□□□□□□，□□□□□□□。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 391. 经行庐山东林寺 ----------
    {
        "id": "xu-hun-391",
        "title": "经行庐山东林寺",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷62》",
        "verse": [
            "离魂断续楚江壖，叶坠初红十月天。紫陌事多难数悉，",
            "青山长在好闲眠。方趋上国期干禄，未得空堂学坐禅。",
            "他岁若教如范蠡，也应须入五湖烟。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 392. 途中逢故人，话西山读书早曾游览 ----------
    {
        "id": "xu-hun-392",
        "title": "途中逢故人，话西山读书早曾游览",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷63》",
        "verse": [
            "西岩曾到读书堂，穿竹行沙十里强。湖上梦馀波滟滟，",
            "岭头愁断路茫茫。经过事寄烟霞远，名利尘随日月长。",
            "莫道少年头不白，君看潘岳几茎霜。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 393. 将赴京题陵阳王氏水居 ----------
    {
        "id": "xu-hun-393",
        "title": "将赴京题陵阳王氏水居",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷64》",
        "verse": [
            "帘卷平芜接远天，暂宽行役到尊前。是非境里有闲日，",
            "荣辱尘中无了年。山簇暮云千野雨，江分秋水九条烟。",
            "马蹄不道贪西去，争向一声高树蝉。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 394. 冬日五浪馆水亭怀别 ----------
    {
        "id": "xu-hun-394",
        "title": "冬日五浪馆水亭怀别",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷65》",
        "verse": [
            "芦荻花多触处飞，独凭虚槛雨微微。寒林叶落鸟巢出，",
            "古渡浪高鱼艇稀。云抱四山终日在，草荒三径几时归。",
            "江城向暝东风急，一半乡愁闻捣衣。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 395. 送别 ----------
    {
        "id": "xu-hun-395",
        "title": "送别",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷66》",
        "verse": [
            "溪边杨柳色参差，攀折年年赠别离。一片风帆望已极，",
            "三湘烟水返何时。多缘去棹将愁远，犹倚危楼欲下迟。",
            "莫殢酒杯闲过日，碧云深处是佳期。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 396. 寄远 ----------
    {
        "id": "xu-hun-396",
        "title": "寄远",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷67》",
        "verse": [
            "两叶愁眉愁不开，独含惆怅上层台。碧云空断雁行处，",
            "红叶已凋人未来。塞外音书无信息，道傍车马起尘埃。",
            "功名待寄凌烟阁，力尽辽城不肯回。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 397. 新柳 ----------
    {
        "id": "xu-hun-397",
        "title": "新柳",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷68》",
        "verse": [
            "无力摇风晓色新，细腰争妒看来频。绿阴未覆长堤水，",
            "金穗先迎上苑春。几处伤心怀远路，一枝和日送行尘。",
            "东□门外多离别，愁杀朝朝暮暮人。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 398. 旅怀作 ----------
    {
        "id": "xu-hun-398",
        "title": "旅怀作",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷69》",
        "verse": [
            "促促因吟昼短诗，朝惊秾色暮空枝。无情春色不长久，",
            "有限年光多盛衰。往事只应随梦里，劳生何处是闲时。",
            "眼前扰扰日一日，暗送白头人不知。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 399. 雁 ----------
    {
        "id": "xu-hun-399",
        "title": "雁",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷70》",
        "verse": [
            "万里衔芦别故乡，云飞水宿向潇湘。数声孤枕堪垂泪，",
            "几处高楼欲断肠。度日翩翩斜避影，临风一一直成行。",
            "年年辛苦来衡岳，羽翼摧残陇塞霜。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 400. 出关 ----------
    {
        "id": "xu-hun-400",
        "title": "出关",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷71》",
        "verse": [
            "朝缨初解佐江滨，麋鹿心知自有群。汉囿猎稀慵献赋，",
            "楚山耕早任移文。卧归渔浦月连海，行望凤城花隔云。",
            "关吏不须迎马笑，去时无意学终军。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 401. 寄房千里博士 ----------
    {
        "id": "xu-hun-401",
        "title": "寄房千里博士",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷72》",
        "verse": [
            "春风白马紫丝缰，正值蚕眠未采桑。五夜有心随暮雨，",
            "百年无节待秋霜。重寻绣带朱藤合，更认罗裙碧草长。",
            "为报西游减离恨，阮郎才去嫁刘郎。",
            "第五百三十七卷",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 402. 泛五云溪 ----------
    {
        "id": "xu-hun-402",
        "title": "泛五云溪",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷1》",
        "verse": [
            "此溪何处路，遥问白髯翁。佛庙千岩里，人家一岛中。",
            "鱼倾荷叶露，蝉噪柳林风。急濑鸣车轴，微波漾钓筒。",
            "石苔萦棹绿，山果拂舟红。更就千村宿，溪桥与剡通。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 403. 寄郴州李相公 ----------
    {
        "id": "xu-hun-403",
        "title": "寄郴州李相公",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷2》",
        "verse": [
            "高楼王与谢，逸韵比南金。不遇销忧日，埃尘谁复寻。",
            "旷怀澹得丧，失意纵登临。彩槛浮云迥，绮窗明月深。",
            "虬龙压沧海，鸳鸾思邓林。青云伤国器，白发轸乡心。",
            "功高恩自洽，道直谤徒侵。应笑灵均恨，江畔独行吟。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 404. 赠萧炼师 ----------
    {
        "id": "xu-hun-404",
        "title": "赠萧炼师",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷3》",
        "verse": [
            "曾试昭阳曲，瑶斋帝自临。红珠络绣帽，翠钿束罗襟。",
            "双阙胡尘起，千门宿露阴。出宫迷国步，回驾轸皇心。",
            "桂殿春空晚，椒房夜自深。急宣求故剑，冥契得遗簪。",
            "暗记神仙传，潜封女史箴。壶中知日永，掌上畏年侵。",
            "莫比班家扇，宁同卓氏琴。云车辞凤辇，羽帔别鸳衾。",
            "网断鱼游藻，笼开鹤戏林。洛烟浮碧汉，嵩月上丹岑。",
            "露草争三秀，风篁共八音。吹笙延鹤舞，敲磬引龙吟。",
            "旄节纤腰举，霞杯皓腕斟。还磨照宝镜，犹插辟寒金。",
            "东海人情变，南山圣寿沈。朱颜常似渥，绿发已如寻。",
            "养气齐生死，留形尽古今。更求应不见，鸡犬日駸駸。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 405. 冬日宣城开元寺赠元孚上人 ----------
    {
        "id": "xu-hun-405",
        "title": "冬日宣城开元寺赠元孚上人",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷4》",
        "verse": [
            "一钵事南宗，僧仪称病容。曹溪花里别，萧寺竹前逢。",
            "烛影深寒殿，经声彻曙钟。欲斋檐睡鸽，初定壁吟蛩。",
            "诗继休遗韵，书传永逸踪。艺多人誉洽，机绝道情浓。",
            "汲涧瓶沈藻，眠阶锡挂松。云鸣新放鹤，池卧旧降龙。",
            "露茗山厨焙，霜粳野碓舂。梵文明处译，禅衲暖时缝。",
            "层塔题应遍，飞轩步不慵。绣梁交薜荔，画井倒芙蓉。",
            "翠户垂旗网，朱窗列剑锋。寒风金磬远，晴雪玉楼重。",
            "妙理三乘达，清才万象供。山高横睥睨，滩浅聚艨艟。",
            "微雾苍平楚，残晖淡远峰。林疏霜摵摵，波静月溶溶。",
            "剑出因雷焕，琴全遇蔡邕。西方知有社，支许合相从。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 406. 维舟秦淮过温州李给事宅 ----------
    {
        "id": "xu-hun-406",
        "title": "维舟秦淮过温州李给事宅",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷5》",
        "verse": [
            "给事为郎日，青溪醉隐衔。冰池通极浦，雪径绕高岩。",
            "珠玉砂同弃，松筠草共芟。帝图忧一失，臣节耻三缄。",
            "代有王陵戆，时无靳尚谗。定应标直笔，宁为发空函。",
            "雾黑连云栈，风狂截海帆。石梯迎雨润，沙井带潮咸。",
            "蜡屐青筇杖，篮舆白罽衫。应劳北归梦，山路正巉巉。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 407. 登蒜山观发军 ----------
    {
        "id": "xu-hun-407",
        "title": "登蒜山观发军",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷6》",
        "verse": [
            "羽檄征兵急，辕门选将雄。犬羊忧破竹，貔虎极飞蓬。",
            "定系猖狂虏，何烦矍铄翁。更探黄石略，重振黑山功。",
            "别马嘶营柳，惊乌散井桐。低星连宝剑，残月让雕弓。",
            "浪晓戈鋋里，山晴鼓角中。甲开鱼照水，旗飏虎拏风。",
            "去想金河远，行知玉塞空。汉庭应有问，师律在元戎。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 408. 送从兄别驾归蜀 ----------
    {
        "id": "xu-hun-408",
        "title": "送从兄别驾归蜀",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷7》",
        "verse": [
            "闻与湘南令，童年侍玉墀。家留秦塞曲，官谪瘴溪湄。",
            "道直奸臣屏，冤深圣主知。逝川东去疾，霈泽北来迟。",
            "青汉龙髯绝，苍岑马鬣移。风凄闻笛处，月惨罢琴时。",
            "客路黄公庙，乡关白帝祠。已称鹦鹉赋，宁诵鶺鴒诗。",
            "远道书难达，长亭酒莫持。当凭蜀江水，万里寄相思。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 409. 金陵阻风登延祚阁 ----------
    {
        "id": "xu-hun-409",
        "title": "金陵阻风登延祚阁",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷8》",
        "verse": [
            "极目皆陈迹，披图问远公。戈鋋三国后，冠盖六朝中。",
            "葛蔓交残垒，芒花没后宫。水流箫鼓绝，山在绮罗空。",
            "极浦千艘聚，高台一径通。云移吴岫雨，潮转楚江风。",
            "登阁渐漂梗，停舟忆断蓬。归期与归路，杉桂海门东。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 410. 送林处士自闽中道越由霅抵两川 ----------
    {
        "id": "xu-hun-410",
        "title": "送林处士自闽中道越由霅抵两川",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷9》",
        "verse": [
            "书剑少青眼，烟波初白头。乡关背梨岭，客路转蘋洲。",
            "处困道难固，乘时恩易酬。镜中非访戴，剑外欲依刘。",
            "高枕海天暝，落帆江雨秋。鼍声应远鼓，蜃气学危楼。",
            "智士役千虑，达人经百忧。唯闻陶靖节，多在醉乡游。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 411. 宣城赠萧兵曹 ----------
    {
        "id": "xu-hun-411",
        "title": "宣城赠萧兵曹",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷10》",
        "verse": [
            "桂楫谪湘渚，三年波上春。舟寒剡溪雪，衣破洛城尘。",
            "客道耻摇尾，皇恩宽犯鳞。花时去国远，月夕上楼频。",
            "贪酒不辞病，佣书非为贫。行吟值渔父，坐隐对樵人。",
            "紫陌罢双辙，碧潭穷一纶。高歌更南去，烟水是通津。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 412. 秋夕宴李侍御宅 ----------
    {
        "id": "xu-hun-412",
        "title": "秋夕宴李侍御宅",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷11》",
        "verse": [
            "公子徵词客，秋堂递玉杯。月高罗幕卷，风度锦屏开。",
            "凤管添簧品，鹍弦促柱哀。转喉云旋合，垂手露徐来。",
            "烛换三条烬，香销十炷灰。蛩声闻鼓歇，萤焰触帘回。",
            "广槛烟分柳，空庭露积苔。解酲须满酌，应为拨新醅。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 413. 晨自竹径至龙兴寺崇隐上人院 ----------
    {
        "id": "xu-hun-413",
        "title": "晨自竹径至龙兴寺崇隐上人院",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷12》",
        "verse": [
            "佛寺通南径，僧堂倚北坡。藤阴迷晚竹，苔滑仰晴莎。",
            "病忆春前别，闲宜雨后过。石横闻水远，林缺见山多。",
            "欲结三天社，初降十地魔。毒龙来有窟，灵鹤去无窠。",
            "客路随萍梗，乡园失薜萝。禅心如可学，不藉鲁阳戈。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 414. 岁暮自广江至新兴往复中题峡山寺四首 ----------
    {
        "id": "xu-hun-414",
        "title": "岁暮自广江至新兴往复中题峡山寺四首",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷13》",
        "verse": [
            "夜醉晨方醒，孤吟恐失群。海鰌潮上见，江鹄雾中闻。",
            "未腊梅先实，经冬草自薰。树随山崦合，泉到石棱分。",
            "虎迹空林雨，猿声绝岭云。萧萧异乡鬓，明日共丝棼。",
            "薄暮缘西峡，停桡一访僧。鹭巢横卧柳，猿饮倒垂藤。",
            "水曲岩千叠，云重树百层。山风寒殿磬，溪雨夜船灯。",
            "滩涨危槎没，泉冲怪石崩。中台一襟泪，岁杪别良朋。",
            "密树分苍壁，长溪抱碧岑。海风闻鹤远，潭日见鱼深。",
            "松盖环清韵，榕根架绿阴。洞丁多斫石，蛮女半淘金。",
            "南浦惊春至，西楼送月沉。江流不过岭，何处寄归心。",
            "月在行人起，千峰复万峰。海虚争翡翠，溪逻斗芙蓉。",
            "古木高生槲，阴池满种松。火探深洞燕，香送远潭龙。",
            "蓝坞寒先烧，禾堂晚并舂。更投何处宿，西峡隔云钟。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 415. 南海使院对菊怀丁卯别墅 ----------
    {
        "id": "xu-hun-415",
        "title": "南海使院对菊怀丁卯别墅",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷14》",
        "verse": [
            "何处曾移菊，溪桥鹤岭东。篱疏还有艳，园小亦无丛。",
            "日晚秋烟里，星繁晓露中。影摇金涧水，香染玉潭风。",
            "罢酒惭陶令，题诗答谢公。朝来数花发，身在尉佗宫。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 416. 和李相国 ----------
    {
        "id": "xu-hun-416",
        "title": "和李相国",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷15》",
        "verse": [
            "巨实珍吴果，驯雏重越禽。摘来渔浦上，携在兔园阴。",
            "霜合凝丹颊，风披敛素襟。刀分琼液散，笼簌雪华深。",
            "虎帐斋中设，龙楼洛下吟。含消兼受彩，应贵冢卿心。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 417. 陪少师李相国崔宾客宴居守狄仆射池亭 ----------
    {
        "id": "xu-hun-417",
        "title": "陪少师李相国崔宾客宴居守狄仆射池亭",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷16》",
        "verse": [
            "池色似潇湘，仙舟正日长。燕飞惊蛱蝶，鱼跃动鸳鸯。",
            "云聚歌初转，风回舞欲翔。暖醅松叶嫩，寒粥杏花香。",
            "罗绮留春色，笙竽送晚光。何须明月夜，红烛在华堂。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 418. 和宾客相国咏雪 ----------
    {
        "id": "xu-hun-418",
        "title": "和宾客相国咏雪",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷17》",
        "verse": [
            "近腊千岩白，迎春四气催。云阴连海起，风急度山来。",
            "尽日隋堤絮，经冬越岭梅。艳疑歌处散，轻似舞时回。",
            "道蕴诗传丽，相如赋骋才。霁添松筱媚，寒积蕙兰猜。",
            "暗涨宫池水，平封辇路埃。烛龙初照耀，巢鹤乍裴回。",
            "檐日琼先挂，墙风粉旋摧。五门环玉垒，双阙对瑶台。",
            "绮席陵寒坐，珠帘远曙开。灵芝霜下秀，仙桂月中栽。",
            "卷幌书千帙，援琴酒百杯。垂休编太史，呈瑞表中台。",
            "皓夜迷三径，浮光彻九垓。兹辰是丰岁，歌咏属良哉。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 419. 奉和卢大夫新立假山 ----------
    {
        "id": "xu-hun-419",
        "title": "奉和卢大夫新立假山",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷18》",
        "verse": [
            "岩谷留心赏，为山极自然。孤峰空迸笋，攒萼旋开莲。",
            "黛色朱楼下，云形绣户前。砌尘凝积霭，檐溜挂飞泉。",
            "树暗壶中月，花香洞里天。何如谢康乐，海峤独题篇。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 420. 奉命和后池十韵 ----------
    {
        "id": "xu-hun-420",
        "title": "奉命和后池十韵",
        "author": "许浑",
        "poet_id": "xu-hun",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷19》",
        "verse": [
            "叠石通溪水，量波失旧规。芳洲还屈曲，朱阁更逶迤。",
            "浴鸟翻荷叶，惊蝉出柳丝。翠烟秋桧耸，红露晓莲披。",
            "攀槛登楼近，停桡待客迟。野桥从浪没，轻舸信风移。",
            "竹韵迁棋局，松阴递酒卮。性闲鸥自识，心远鹤先知。",
            "应想秦人会，休怀越相祠。当期穆天子，箫鼓宴瑶池。",
            "第五百三十八卷",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
